func test_trino_TestTrino_test_inline_udf(self *Case, a Args) Value {
	self.L(491).ValidateIdentity("WITH FUNCTION f(num INTEGER) RETURNS INTEGER RETURN num SELECT F(1)")
	self.L(494).ValidateIdentity("WITH FUNCTION hello(name VARCHAR) RETURNS VARCHAR RETURN FORMAT('Hello %s!', name), FUNCTION bye() RETURNS VARCHAR RETURN 'Bye!' SELECT HELLO('Finn') || BYE()")
	self.L(499).ValidateIdentity("WITH FUNCTION doubled(x INTEGER) RETURNS INTEGER RETURN x * 2 WITH t AS (SELECT 3 AS v) SELECT DOUBLED(v) FROM t")
	self.L(503).ValidateIdentity("WITH FUNCTION f(x INTEGER) RETURNS INTEGER RETURN x WITH RECURSIVE t(n) AS (SELECT 1 AS n) SELECT F(n) FROM t")
	self.L(507).ValidateIdentity("WITH FUNCTION f(num int)\n    RETURNS int\n    RETURN num\nSELECT f(1)", "WITH FUNCTION f(num INTEGER) RETURNS INTEGER RETURN num SELECT F(1)")
	self.L(514).ValidateIdentity("WITH function AS (SELECT 1 AS x) SELECT x FROM function")
	self.L(515).ValidateIdentity("WITH function(x) AS (SELECT 1) SELECT x FROM function")
	self.L(517).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER LANGUAGE SQL RETURN 1 SELECT F()")
	self.L(518).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER DETERMINISTIC RETURN 1 SELECT F()")
	self.L(521).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER NOT DETERMINISTIC RETURN 1 SELECT F()")
	self.Do(524, func() {
		M(self, "assertIsInstance", Item(A(self.ValidateIdentity("SELECT NOT deterministic FROM t"), "selects"), 0), A(G("sqlglot.exp"), "Not"))
	})
	self.L(527).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER CALLED ON NULL INPUT RETURN 1 SELECT F()")
	self.L(530).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER RETURNS NULL ON NULL INPUT RETURN 1 SELECT F()")
	self.L(533).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER COMMENT 'hi' RETURN 1 SELECT F()")
	self.L(541).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER SECURITY DEFINER RETURN 1 SELECT F()")
	self.L(544).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER SECURITY INVOKER RETURN 1 SELECT F()")
	self.L(547).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER WITH (weight=42) RETURN 1 SELECT F()")
	self.L(550).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER LANGUAGE SQL WITH (weight=42, cost='low') RETURN 1 SELECT F()")
	self.L(554).ValidateIdentity("WITH FUNCTION custom_sqrt(a INTEGER) RETURNS DOUBLE COMMENT 'Custom sqrt function' RETURNS NULL ON NULL INPUT NOT DETERMINISTIC LANGUAGE SQL SECURITY DEFINER WITH (weight=42, cost='low') RETURN a SELECT CUSTOM_SQRT(4)")
	return nil
}

func test_trino_TestTrino_test_inline_udf_begin_end(self *Case, a Args) Value {
	self.L(562).ValidateIdentity("WITH FUNCTION meaning_of_life() RETURNS INTEGER BEGIN DECLARE a INTEGER DEFAULT 6; DECLARE b INTEGER DEFAULT 7; RETURN a * b; END SELECT MEANING_OF_LIFE()")
	self.L(569).ValidateIdentity("WITH FUNCTION one() RETURNS INTEGER BEGIN DECLARE counter INTEGER DEFAULT 1; SET counter = 0; SET counter = counter + 2; SET counter = counter / counter; RETURN counter; END SELECT ONE()")
	self.L(578).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER BEGIN DECLARE first_name, last_name, middle_name VARCHAR(25); RETURN 1; END SELECT F()")
	self.L(585).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER BEGIN DECLARE x INTEGER DEFAULT 1; BEGIN SET x = x + 1; END; RETURN x; END SELECT F()")
	self.L(592).ValidateIdentity("SELECT declare FROM (VALUES (1), (2)) AS t(declare)")
	self.L(593).ValidateIdentity("WITH FUNCTION declare() RETURNS INTEGER RETURN 1 SELECT DECLARE()")
	self.Do(597, func() {
		self.AssertEqual(M(M(G("sqlglot.exp"), "Block", Kw("expressions", NewList(Call(G("sqlglot.parse_one"), "SELECT 1"), Call(G("sqlglot.parse_one"), "SELECT 2"), M(G("sqlglot.exp"), "EndStatement")))), "sql", Kw("dialect", "trino")), "SELECT 1; SELECT 2; END")
	})
	return nil
}

func test_trino_TestTrino_test_inline_udf_if(self *Case, a Args) Value {
	self.L(610).ValidateIdentity("WITH FUNCTION simple_if(a BIGINT) RETURNS VARCHAR BEGIN IF a = 0 THEN RETURN 'zero'; ELSEIF a = 1 THEN RETURN 'one'; ELSE RETURN 'more than one or negative'; END IF; END SELECT SIMPLE_IF(3)")
	self.L(618).ValidateIdentity("WITH FUNCTION f(a INTEGER) RETURNS VARCHAR BEGIN IF a = 0 THEN RETURN 'zero'; END IF; RETURN 'other'; END SELECT F(1)")
	self.L(625).ValidateIdentity("WITH FUNCTION f(a INTEGER) RETURNS VARCHAR BEGIN IF a = 0 THEN RETURN 'zero'; ELSEIF a = 1 THEN RETURN 'one'; END IF; RETURN 'other'; END SELECT F(1)")
	self.L(634).ValidateIdentity("WITH FUNCTION f(a INTEGER, b INTEGER) RETURNS VARCHAR BEGIN IF a = 0 THEN IF b = 0 THEN RETURN 'both zero'; ELSE RETURN 'a zero'; END IF; ELSE RETURN 'a nonzero'; END IF; RETURN 'unreachable'; END SELECT F(1, 2)")
	self.L(643).ValidateIdentity("WITH FUNCTION f(a INTEGER) RETURNS INTEGER BEGIN DECLARE result INTEGER DEFAULT 0; IF a > 0 THEN RETURN CASE WHEN a > 10 THEN 1 ELSE 2 END; ELSE SET result = -1; END IF; RETURN result; END SELECT F(1)")
	self.L(654).ValidateIdentity("WITH FUNCTION f() RETURNS INTEGER LANGUAGE SQL NOT DETERMINISTIC BEGIN DECLARE x INTEGER DEFAULT 1; RETURN x; END SELECT F()")
	self.L(659).ValidateIdentity("WITH FUNCTION doubled(x INTEGER) RETURNS INTEGER BEGIN RETURN x * 2; END WITH t AS (SELECT 3 AS v) SELECT DOUBLED(v) FROM t")
	return nil
}

func test_trino_TestTrino_test_inline_udf_case(self *Case, a Args) Value {
	self.L(670).ValidateIdentity("WITH FUNCTION simple_case(a BIGINT) RETURNS VARCHAR BEGIN CASE a WHEN 0 THEN RETURN 'zero'; WHEN 1 THEN RETURN 'one'; ELSE RETURN 'more than one or negative'; END CASE; RETURN NULL; END SELECT SIMPLE_CASE(0)")
	self.L(679).ValidateIdentity("WITH FUNCTION searched_case(a BIGINT) RETURNS VARCHAR BEGIN CASE WHEN a = 0 THEN RETURN 'zero'; WHEN a = 1 THEN RETURN 'one'; ELSE RETURN 'other'; END CASE; RETURN NULL; END SELECT SEARCHED_CASE(0)")
	self.L(689).ValidateIdentity("WITH FUNCTION no_else(a BIGINT) RETURNS VARCHAR BEGIN CASE a WHEN 0 THEN RETURN 'zero'; END CASE; RETURN 'fallthrough'; END SELECT NO_ELSE(0)")
	self.L(696).ValidateIdentity("WITH FUNCTION no_operand_no_else(a INTEGER) RETURNS VARCHAR BEGIN CASE WHEN a = 0 THEN RETURN 'zero'; END CASE; RETURN 'other'; END SELECT NO_OPERAND_NO_ELSE(1)")
	self.L(704).ValidateIdentity("WITH FUNCTION nested_case(a BIGINT, b BIGINT) RETURNS VARCHAR BEGIN DECLARE result VARCHAR; CASE WHEN a = 0 THEN CASE b WHEN 0 THEN SET result = 'a0b0'; ELSE SET result = 'a0bN'; END CASE; ELSE SET result = 'aN'; END CASE; RETURN result; END SELECT NESTED_CASE(0, 0)")
	self.L(715).ValidateIdentity("WITH FUNCTION mix(a INTEGER) RETURNS INTEGER BEGIN DECLARE result INTEGER DEFAULT 0; CASE WHEN a > 0 THEN IF a > 10 THEN SET result = 1; ELSE SET result = 2; END IF; ELSE SET result = CASE WHEN a < -10 THEN -1 ELSE -2 END; END CASE; RETURN result; END SELECT MIX(1)")
	self.L(730).ValidateIdentity("WITH FUNCTION last_stmt(a INTEGER) RETURNS VARCHAR BEGIN CASE a WHEN 0 THEN RETURN 'zero'; ELSE RETURN 'other'; END CASE; END SELECT LAST_STMT(1)")
	return nil
}

func test_trino_TestTrino_test_inline_udf_while(self *Case, a Args) Value {
	self.L(742).ValidateIdentity("WITH FUNCTION npow(n BIGINT) RETURNS BIGINT BEGIN DECLARE r BIGINT DEFAULT 1; DECLARE p BIGINT DEFAULT n; WHILE p > 1 DO SET r = r * n; SET p = p - 1; END WHILE; RETURN r; END SELECT NPOW(5)")
	self.L(753).ValidateIdentity("WITH FUNCTION npow_labeled(n BIGINT) RETURNS BIGINT BEGIN DECLARE r BIGINT DEFAULT 1; DECLARE p BIGINT DEFAULT n; abc: WHILE p > 1 DO SET r = r * n; SET p = p - 1; END WHILE; RETURN r; END SELECT NPOW_LABELED(5)")
	self.L(766).ValidateIdentity("WITH FUNCTION last_stmt(n BIGINT) RETURNS BIGINT BEGIN DECLARE r BIGINT DEFAULT 1; WHILE r < n DO SET r = r + 1; END WHILE; END SELECT LAST_STMT(5)")
	self.L(774).ValidateIdentity("WITH FUNCTION count_evens(n BIGINT) RETURNS BIGINT BEGIN DECLARE total BIGINT DEFAULT 0; DECLARE i BIGINT DEFAULT 0; WHILE i < n DO SET total = total + 1; IF i = 0 THEN SET total = total + 1; END IF; SET i = i + 1; END WHILE; RETURN total; END SELECT COUNT_EVENS(3)")
	self.L(782).ValidateIdentity("WITH FUNCTION while_case(n BIGINT) RETURNS BIGINT BEGIN DECLARE i BIGINT DEFAULT 0; WHILE i < n DO CASE WHEN i = 0 THEN SET i = 1; ELSE SET i = i + 1; END CASE; END WHILE; RETURN i; END SELECT WHILE_CASE(3)")
	return nil
}

func test_trino_TestTrino_test_inline_udf_loop_repeat(self *Case, a Args) Value {
	var loop_ast, repeat_ast, node, cm Value
	_ = []Value{loop_ast, repeat_ast, node, cm}
	self.Do(794, func() {
		loop_ast = self.ValidateIdentity("WITH FUNCTION to_one_hundred(start_value BIGINT, step BIGINT) RETURNS BIGINT BEGIN DECLARE count BIGINT DEFAULT 0; DECLARE current BIGINT DEFAULT 0; SET current = start_value; abc: LOOP IF current >= 100 THEN LEAVE abc; END IF; SET count = count + 1; SET current = current + step; END LOOP; RETURN count; END SELECT TO_ONE_HUNDRED(0, 10)")
	})
	self.L(808).ValidateIdentity("WITH FUNCTION test_repeat(a BIGINT) RETURNS BIGINT BEGIN REPEAT SET a = a + 1; UNTIL a >= 10 END REPEAT; RETURN a; END SELECT TEST_REPEAT(5)")
	self.Do(818, func() {
		repeat_ast = self.ValidateIdentity("WITH FUNCTION iter_count() RETURNS BIGINT BEGIN DECLARE a BIGINT DEFAULT 0; DECLARE b BIGINT DEFAULT 0; top: REPEAT SET a = a + 1; IF a <= 3 THEN ITERATE top; END IF; SET b = b + 1; UNTIL a >= 10 END REPEAT; RETURN b; END SELECT ITER_COUNT()")
	})
	self.L(830).ValidateIdentity("WITH FUNCTION nested_test(n BIGINT) RETURNS BIGINT BEGIN DECLARE total BIGINT DEFAULT 0; DECLARE i BIGINT DEFAULT 0; DECLARE j BIGINT DEFAULT 0; outer_loop: WHILE i < n DO SET j = 0; inner_loop: LOOP IF j >= 3 THEN LEAVE inner_loop; END IF; SET total = total + 1; SET j = j + 1; END LOOP; SET i = i + 1; END WHILE; RETURN total; END SELECT NESTED_TEST(2)")
	self.L(846).ValidateIdentity("WITH FUNCTION last_stmt(n BIGINT) RETURNS BIGINT BEGIN DECLARE i BIGINT DEFAULT 0; top: LOOP IF i >= n THEN LEAVE top; END IF; SET i = i + 1; END LOOP; END SELECT LAST_STMT(5)")
	self.L(857).ValidateIdentity("WITH FUNCTION label_test(n BIGINT) RETURNS BIGINT BEGIN DECLARE i BIGINT DEFAULT 0; iterate: LOOP IF i >= n THEN LEAVE iterate; END IF; SET i = i + 1; END LOOP; RETURN i; END SELECT LABEL_TEST(5)")
	self.L(864).ValidateIdentity("WITH FUNCTION label_test2(n BIGINT) RETURNS BIGINT BEGIN DECLARE i BIGINT DEFAULT 0; leave: LOOP IF i >= n THEN LEAVE leave; END IF; SET i = i + 1; END LOOP; RETURN i; END SELECT LABEL_TEST2(5)")
	self.L(875).ValidateIdentity("WITH FUNCTION label_test3(n BIGINT) RETURNS BIGINT BEGIN DECLARE i BIGINT DEFAULT 0; set: LOOP IF i >= n THEN LEAVE set; END IF; SET i = i + 1; END LOOP; RETURN i; END SELECT LABEL_TEST3(5)")
	for _, item_ := range Iter(NewTuple(Star(M(loop_ast, "find_all", A(G("sqlglot.exp"), "LoopBlock"), A(G("sqlglot.exp"), "Leave"))), Star(M(repeat_ast, "find_all", A(G("sqlglot.exp"), "RepeatBlock"), A(G("sqlglot.exp"), "Iterate"))))) {
		node = item_
		self.Do(889, func() {
			self.AssertLogs(func(cm_ Value) {
				cm = cm_
				M(self, "assertEqual", M(node, "sql"), "")
			}, G("sqlglot.generator.logger"), Kw("level", "WARNING"))
		})
		self.Do(892, func() { M(self, "assertIn", "Unsupported", Item(A(cm, "output"), 0)) })
	}
	return nil
}
